#!/usr/bin/env python3
"""Builds docs/testing/14-coverage-matrix.md from the page catalogues, endpoint catalogue and file inventories. Run from repo root after the other generators."""
import re, json, os, glob, collections
out = ['# 14 — Coverage matrix (proof that every inventory item has tests)', '',
       'Generated by `docs/testing/generated/gen_matrix.py`. A cell with `—` is a **gap** and is listed in §9. "Standard" means the battery defined in `04-e2e-testing.md` §A.', '']
def rows(path, pat):
    r = []
    for l in open(path):
        m = re.match(pat, l)
        if m: r.append(m.groups())
    return r
TYPES = 'E2E · VIS-L · UX-EL · A11Y-AUT/KEY · SEC-RBAC-002 · PERF-UI-001'
# A admin pages
adm = rows('docs/testing/04a-e2e-page-catalogue-admin.md', r'\| (\d{3}) \| `([^`]+)` \| (\w+) \| ([^|]+) \| ([^|]+) \| (\d+) \|')
out += ['## 1. Admin pages (04a)', '', f'{len(adm)} pages with screenshots (4 devices each = {len(adm)*4} images) + pending dynamic/modal states in 04a.', '',
        '| Seq | Route | Battery | Page cases | Screens D/L/T/M | Test types covering the page |', '|---|---|---|---|---|---|']
for seq, route, kind, bat, roles, n in adm:
    shots = all(os.path.exists(f'docs/testing/screenshots/staging-admin-frontend-screenshots/{d}/{seq}_{re.sub(r"[^a-zA-Z0-9]+","-",route).strip("-")[:60] or "root"}.png') or glob.glob(f'docs/testing/screenshots/staging-admin-frontend-screenshots/{d}/{seq}_*.png') for d in ('desktop','laptop','tablet','mobile'))
    out.append(f'| {seq} | `{route}` | {kind} ({bat.strip()}) | PA{seq}.1–{n} | {"✔" if shots else "—"} | {TYPES} |')
# B client pages
cl = rows('docs/testing/04b-e2e-page-catalogue-client.md', r'\| `([^`]+)` \| (\w+) \| ([^|]+) \| ([^|]+) \| ([^|]+) \| (\d+) \|')
out += ['', '## 2. Client portal pages (04b)', '', f'{len(cl)} route entries. Screenshots pending login for all but `/login`.', '', '| Route | Battery | Page cases | Screens | Test types |', '|---|---|---|---|---|']
for i, (route, kind, bat, roles, shot, n) in enumerate(cl, 1):
    out.append(f'| `{route}` | {kind} ({bat.strip()}) | PC{i:03d}.1–{n} | {"✔" if "pending" not in shot else "pending (login)"} | {TYPES} |')
# C endpoints
mods = collections.OrderedDict()
for l in open('docs/testing/generated/ENDPOINT_CATALOGUE.md'):
    m = re.match(r'\| (E\d+) \| ([^|]+) \| (\w+) \|', l)
    if m: mods.setdefault(m.group(2).strip(), []).append(m.group(1))
IT = {'adjustments': 'IT-ORD, IT-INV-004', 'audit-logs': 'IT-PLT-001', 'auth': 'IT-AUT-001..007', 'backups': 'IT-PLT-004', 'billing': 'IT-BIL-001..007', 'client-portal': 'IT-CLI-001..004, IT-TEN, IT-EXT-001',
      'cod': 'IT-FIN-001..003', 'companies': 'IT-TEN, IT-AUT-003', 'cycle-count': 'IT-ORD-012', 'dashboard': 'PERF-API-001', 'final-contracts': 'IT-PLT-005', 'financial': 'IT-FIN-001..008',
      'forms': 'IT-PLT-007', 'inbound': 'IT-ORD-001/004/008', 'inventory': 'IT-INV-001..003', 'locations': 'IT-ORD-001', 'notifications': 'IT-PLT-002', 'observability': 'IT-PLT-008',
      'oms-returns': 'IT-ORD-010', 'oms': 'IT-ORD-005..009, IT-CAR', 'outbound': 'IT-ORD-002/003', 'products': 'IT-ORD-001', 'realtime': 'IT-PLT-003', 'reports': 'PERF-API-010',
      'returns': 'IT-ORD-010', 'settings': 'IT-FX-001, SEC-3P-002', 'shipping': 'IT-CAR-001..011, IT-FX', 'users': 'IT-AUT-005', 'warehouse-workflow': 'IT-ORD-011', 'warehouses': 'IT-ORD-001', 'pdf': 'IT-PLT-005, IT-TEN-007'}
out += ['', '## 3. HTTP endpoints (03) — 594 endpoints × battery EP-01…EP-14', '', '| Module | Endpoints | Range | Scenario tests | Battery |', '|---|---|---|---|---|']
tot = 0
for k, v in mods.items():
    tot += len(v)
    out.append(f'| {k} | {len(v)} | {v[0]}–{v[-1]} | {IT.get(k, "—")} | EP-01…14 + UT per service |')
out.append(f'| **Total** | **{tot}** | | | |')
# D unit gaps
g = sum(1 for l in open('docs/testing/generated/UNIT_GAP_BACKEND.md') if l.startswith('| G'))
f = sum(1 for l in open('docs/testing/generated/UNIT_GAP_FRONTEND.md') if '**NO**' in l)
out += ['', '## 4. Unit-test inventory (01)', '', f'* Backend files without sibling spec: **{g}** → covered by sections 2.1–2.7 of `01` (domain-level cases) — the executor ticks each G-id when its file is covered by a spec (own or domain spec) or moves it to an IT with justification.', f'* Frontend lib/hook/util files without spec: **{f}** → `01` §3 (UT-FE-*, UT-CFE-*).', '']
# E components
nc = len(glob.glob('frontend/src/components/**/*.tsx', recursive=True)); nk = len(glob.glob('client-frontend/src/components/**/*.tsx', recursive=True)) + len(glob.glob('client-frontend/src/design-v2/*.tsx'))
out += ['## 5. Components (02)', '', f'{nc} admin + {nk} client component files; every file gets a case under CT-* groups (shared primitives §1, domain §2, client §3); the executor lists files per folder and records one row each in the results.', '']
# F roles
out += ['## 6. Roles (09, 04)', '', '| Role | RBAC matrix (API) | UI route matrix | Visual role baseline |', '|---|---|---|---|']
for r in 'super_admin, wh_manager, wh_operator, finance (accountant), viewer, inventory_controller, custom role, client_admin, client_staff, anonymous'.split(', '):
    out.append(f'| {r} | SEC-RBAC-001 | SEC-RBAC-002 | VIS (role-specific pages) |')
# G carriers
out += ['', '## 7. Carriers', '', '| Carrier | Unit | Integration | E2E | Security | Mode |', '|---|---|---|---|---|---|']
for c, u, i, e, m in [('Sena', 'UT-SEN-*', 'IT-CAR-001', 'E2E-CAR-001', 'sandbox'), ('Babel', 'UT-BAB-*', 'IT-CAR-002', 'E2E-CAR-002', 'live (approval)'), ('Sila', 'UT-SIL-*', 'IT-CAR-003', 'E2E-CAR-003', 'live (approval)'), ('Delivery Joud', 'UT-DJ-*', 'IT-CAR-004', 'E2E-CAR-004', 'live (approval)'), ('Fatih Cargo', 'UT-FAT-*', 'IT-CAR-005', 'E2E-CAR-005', 'live (approval)'), ('mock-carrier', 'UT-MOCK-001', 'all IT', '—', 'tests only')]:
    out.append(f'| {c} | {u} | {i} | {e} | SEC-WH-001, SEC-3P-001 | {m} |')
# H flows
out += ['', '## 8. Business flows / modules', '', '| Domain | Unit | Integration | E2E | System | UAT |', '|---|---|---|---|---|---|']
for d, a, b, c, s, u in [('Inbound', 'UT-INB-*', 'IT-ORD-001/004', 'E2E-ORD-001..006', 'SYS-SM-003', 'UAT-01'), ('Outbound', 'UT-OUT-*', 'IT-ORD-002/003', 'E2E-ORD-010..013', 'SYS-SM-002', 'UAT-02'), ('OMS', 'UT-OMS-*', 'IT-ORD-005..009', 'E2E-OMS-001..017', 'SYS-SM-001', 'UAT-02..08'),
                         ('Returns', 'UT-RET-*', 'IT-ORD-010', 'E2E-RET-001..003', 'SYS-SM-004/005', 'UAT-06'), ('Tasks/workers', 'UT-TSK-*', 'IT-ORD-011', 'E2E-ORD-002/011', 'SYS-SM-006', 'UAT-17'), ('Inventory', 'UT-INV-*, UT-LED-*', 'IT-INV-*', 'E2E-INV-*', 'SYS-INV-*', 'UAT-01'),
                         ('Cycle count', 'UT-CYC-*', 'IT-ORD-012', 'E2E-INV-004', 'SYS-SM-008', '—'), ('Carriers', 'UT-CAR/SEN/BAB/SIL/DJ/FAT', 'IT-CAR-*', 'E2E-CAR-*', 'SYS-X-001', 'UAT-02/03'), ('Finance', 'UT-FIN-*', 'IT-FIN-*', 'E2E-FIN-*', 'SYS-FIN-*', 'UAT-10/11'),
                         ('Billing', 'UT-BIL-*', 'IT-BIL-*', 'E2E-BIL-*', 'SYS-BIL-*', 'UAT-09'), ('Currency/FX', 'UT-MON/FX-*', 'IT-FX-*', 'E2E-FX-001', 'SYS-CUR-*', 'UAT-14'), ('Auth/users/roles', 'UT-AUT/RBAC-*', 'IT-AUT-*', 'E2E-USR-*, AUTH-*', 'SYS-SM-013', 'UAT-12/16'),
                         ('Client portal', 'UT-CFE-*', 'IT-CLI-*', 'E2E-CLI-*', 'SYS-SM-012', 'UAT-13/17'), ('External API', '—', 'IT-EXT-001', 'E2E-EXT-*', '—', 'UAT-13'), ('Backups', 'UT-BKP-*', 'IT-PLT-004', 'E2E-ADM-003', 'SYS-NF-003', 'UAT-18'),
                         ('Documents/PDF', 'UT-PDF-*', 'IT-PLT-005', 'E2E-X-006', '—', 'UAT-01/20'), ('Reports', 'UT-FE-002', 'PERF-API-010', 'RB battery', '—', 'UAT-15'), ('Audit/notifications', 'UT-AUD/NOT-*', 'IT-PLT-001/002', 'E2E-ADM-001/002', 'SYS-X-004/005', '—')]:
    out.append(f'| {d} | {a} | {b} | {c} | {s} | {u} |')
out += ['', '## 9. Known gaps in the *capture* (not in the test design) — to close at the start of phase 3', '',
        '1. Client portal screenshots (34 routes × 4 devices): need an authenticated client session (owner logs in; agent never types passwords).',
        '2. Admin dynamic routes without screenshots yet: edit pages, task execute, cycle-count detail/execute, WMS returns detail/process, inventory product/ledger detail, billing plan detail/edit, client user detail, COD detail, return plan edit (listed in 04a "Pending").',
        '3. Modals/dialogs/empty/error/403/404 states (04 §C) — to be captured per page while executing.',
        '4. Arabic, dark-mode and role-specific baselines (only super_admin / EN / light captured).',
        '5. Admin login/forgot/reset pages (requires logout) — capture with owner.',
        '6. Lists were captured in their *default filter state*; filtered/selected/expanded states are produced during E2E.', '']
open('docs/testing/14-coverage-matrix.md', 'w').write('\n'.join(out) + '\n')
print('matrix ok', len(adm), len(cl), tot)
